-- Add DAPO method, introduced in arXiv 2503.14476. The source paper
-- gets the source evidence row (Introduced banner); citers are linked by
-- link_papers_by_source_citations.py and the hourly reference backfill.

INSERT INTO methods (
    slug,
    name,
    full_name,
    description,
    keywords,
    area_id,
    introduced_year,
    source_paper_id,
    source_url,
    source_title,
    code_snippet_url,
    image_url,
    image_credit
)
VALUES (
    'dapo',
    'DAPO',
    'Decoupled Clip and Dynamic sAmpling Policy Optimization (DAPO)',
    'DAPO (Decoupled Clip and Dynamic sAmpling Policy Optimization) is a reinforcement learning algorithm for training long chain-of-thought reasoning in large language models with verifiable rewards. It extends [GRPO](/methods/grpo) with four techniques: Clip-Higher decouples the lower and upper clipping ranges of the importance ratio to avoid entropy collapse; Dynamic Sampling drops prompts whose sampled responses are all correct or all wrong, so every batch carries a useful gradient; a token-level policy-gradient loss weights long responses properly; and overlong reward shaping reduces the noise from truncated generations. Trained from the Qwen2.5-32B base model, DAPO reached 50 points on AIME 2024, beating DeepSeek-R1-Zero-Qwen-32B with half the training steps. The release open-sourced the algorithm, training code and the DAPO-Math-17K dataset, and DAPO is a common baseline in [RLVR](/methods/rlvr) work.',
    'DAPO, decoupled clip and dynamic sampling policy optimization',
    (
        SELECT id
        FROM areas
        WHERE name = 'Language'
        LIMIT 1
    ),
    2025,
    (
        SELECT id
        FROM papers
        WHERE arxiv_id = '2503.14476'
        ORDER BY is_latest_version DESC, id DESC
        LIMIT 1
    ),
    NULL,
    'DAPO: An Open-Source LLM Reinforcement Learning System at Scale',
    'https://github.com/BytedTsinghua-SIA/DAPO',
    NULL,
    '[DAPO: An Open-Source LLM Reinforcement Learning System at Scale](/paper/2503.14476)'
)
ON CONFLICT (slug) DO UPDATE
SET
    name = EXCLUDED.name,
    full_name = EXCLUDED.full_name,
    description = EXCLUDED.description,
    keywords = EXCLUDED.keywords,
    area_id = EXCLUDED.area_id,
    introduced_year = EXCLUDED.introduced_year,
    source_paper_id = EXCLUDED.source_paper_id,
    source_url = EXCLUDED.source_url,
    source_title = EXCLUDED.source_title,
    code_snippet_url = EXCLUDED.code_snippet_url,
    image_url = EXCLUDED.image_url,
    image_credit = EXCLUDED.image_credit,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO paper_methods (paper_id, method_id)
SELECT source_paper_id, id
FROM methods
WHERE slug = 'dapo'
  AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT source_paper_id, id, 'source'
FROM methods
WHERE slug = 'dapo'
  AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

